focused_wrapper_source:
param([string]$RepositoryRoot,[string]$ToolRoot,[string]$WorkRoot,[string]$TestPython,[string]$ReportPath)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$RepositoryRoot=(Resolve-Path -LiteralPath $RepositoryRoot).ProviderPath
$ToolRoot=(Resolve-Path -LiteralPath $ToolRoot).ProviderPath
$WorkRoot=(Resolve-Path -LiteralPath $WorkRoot).ProviderPath
$TestPython=(Resolve-Path -LiteralPath $TestPython).ProviderPath
$oldTemp=$env:TEMP; $oldTmp=$env:TMP
try {
    $env:TEMP=$WorkRoot; $env:TMP=$WorkRoot
    Import-Module (Join-Path $ToolRoot 'Pester/6.2.0/Pester.psd1') -Force -ErrorAction Stop
    $config=New-PesterConfiguration
    $names=@('Manager.Tests.ps1','Discovery.Tests.ps1','Process.Tests.ps1','Runtime.Tests.ps1')
    $config.Run.Container=@(foreach($name in $names){New-PesterContainer -Path (Join-Path $RepositoryRoot ('tests/powershell/'+$name)) -Data @{RepositoryRoot=$RepositoryRoot;WorkRoot=$WorkRoot;TestPython=$TestPython}})
    $config.Run.PassThru=$true; $config.Run.Exit=$false; $config.Output.Verbosity='Detailed'
    $result=Invoke-Pester -Configuration $config
    $record=[ordered]@{schema_version=1;task='T02';kind='FOCUSED_MAINTAINED_COMPONENT_AND_PROCESS_REGRESSION';host=$PSVersionTable.PSVersion.ToString();policy=(Get-ExecutionPolicy).ToString();result=$result.Result.ToString();total=$result.TotalCount;passed=$result.PassedCount;failed=$result.FailedCount;skipped=$result.SkippedCount;not_run=$result.NotRunCount;failed_containers=$result.FailedContainersCount;
        test_python=$TestPython;test_sha256=@(foreach($name in $names){@{path=('tests/powershell/'+$name);sha256=(Get-FileHash -LiteralPath (Join-Path $RepositoryRoot ('tests/powershell/'+$name)) -Algorithm SHA256).Hash.ToLowerInvariant()}});
        failed_cases=@($result.Failed|ForEach-Object{@{name=$_.ExpandedPath;errors=@($_.ErrorRecord|ForEach-Object{$_.Exception.Message})}});container_errors=@($result.FailedContainers|ForEach-Object{@($_.ErrorRecord|ForEach-Object{$_.Exception.Message})})}
    $stream=[IO.File]::Open($ReportPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
    try{$writer=New-Object IO.StreamWriter($stream,(New-Object Text.UTF8Encoding($false)));try{$writer.Write(($record|ConvertTo-Json -Depth 12))}finally{$writer.Dispose()}}finally{$stream.Dispose()}
    if($result.FailedCount -or $result.FailedContainersCount){exit 1}
    exit 0
}finally{$env:TEMP=$oldTemp;$env:TMP=$oldTmp}
